import requests, time, re, html, concurrent.futures
queries=[
 '\"10x Genomics\" \"Mus musculus\" \"brain\"',
 '\"10x Genomics\" \"Mus musculus\" \"cortex\"',
 '\"10x Genomics\" \"Mus musculus\" \"neural\"',
 '\"10x\" \"Mus musculus\" \"cortical\"',
 '\"10x\" \"Mus musculus\" \"forebrain\"',
 '\"10x\" \"Mus musculus\" \"embryonic\" \"brain\"',
]
items={}
for q in queries:
    r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'gds','term':q,'retmax':'800','retmode':'json','tool':'codex','email':'nobody@example.com'},timeout=15)
    try: ids=r.json()['esearchresult'].get('idlist',[])
    except Exception: continue
    for cs in range(0,len(ids),50):
        chunk=ids[cs:cs+50]
        try: js=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'gds','id':','.join(chunk),'retmode':'json','tool':'codex','email':'nobody@example.com'},timeout=15).json().get('result',{})
        except Exception: continue
        for id in chunk:
            it=js.get(id,{})
            acc=it.get('accession')
            if acc and acc.startswith('GSE'): items[acc]=it
        time.sleep(0.35)
    time.sleep(0.35)
print('items',len(items))

def prefix(acc):
    n=int(acc[3:]); return f'GSE{n//1000:03d}nnn/{acc}'

def fetch(acc):
    base=f'https://ftp.ncbi.nlm.nih.gov/geo/series/{prefix(acc)}/suppl/'
    blobs=[]
    try:
        txt=requests.get(base,timeout=3).text
        blobs.append(txt)
        if 'filelist.txt' in txt:
            try: blobs.append(requests.get(base+'filelist.txt',timeout=3).text)
            except Exception: pass
    except Exception:
        return None
    blob='\\n'.join(blobs)
    if not (('matrix.mtx' in blob or 'filtered_feature_bc_matrix.h5' in blob) and ('barcodes' in blob or 'filtered_feature_bc_matrix.h5' in blob)):
        return None
    # keep hits with useful file sizes / names
    lines=[]
    for ln in blob.splitlines():
        if any(k in ln for k in ['features.tsv.gz','genes.tsv.gz','barcodes.tsv.gz','matrix.mtx.gz','filtered_feature_bc_matrix.h5']):
            clean=re.sub('<["'^>]+>'"',' ',ln)
            clean=html.unescape(re.sub(r'\\s+',' ',clean)).strip()
            lines.append(clean)
    if not lines: return None
    # score for likely target
    text='\\n'.join(lines)
    score=0
    if re.search(r'features\\.tsv\\.gz.*(?:28[0-9]{4}|29[0-9]{4}|290[0-9]{3}|[ ]29[0-9]K)', text): score+=3
    if re.search(r'matrix\\.mtx\\.gz.*(?:[5-9][0-9]M|1[0-5][0-9]M)', text): score+=2
    if 'filtered_feature_bc_matrix.h5' in text: score+=2
    title=items[acc].get('title','')
    if any(w.lower() in title.lower() for w in ['cortex','cortical','neural','neuro','forebrain','brain','progenitor']): score+=1
    return (score,acc,items[acc].get('pdat',''),title[:120],items[acc].get('ssinfo','')[:60],lines[:20])

hits=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=16) as ex:
    futs=[ex.submit(fetch,acc) for acc in items]
    for fut in concurrent.futures.as_completed(futs):
        res=fut.result()
        if res: hits.append(res)
print('hits',len(hits))
for score,acc,pdat,title,ss,lines in sorted(hits, reverse=True)[:120]:
    print('\\n### score',score,acc,pdat,'SS',ss,'TITLE',title)
    for ln in lines: print(ln)
